// ELEMENTS:
// 1. Foto/vídeo (src) em ecrã inteiro que vai sendo enquadrado por barras navy (formato cinema)
// 2. Pan lateral lento dentro da faixa
// 3. Barra de cima: eyebrow (eyebrow) branco sublinhado a azul IAD
// 4. Barra de baixo: legenda em serifa branca (anim.text)
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#161617";
const CYAN = "#FFFFFF";
const CORAL = "#FFFFFF";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.26) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const LetterboxCinema: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const eyebrow = String(p.eyebrow ?? "").trim();
  const caption = String(anim.text ?? "").trim();

  // Portrait keeps a tall band (a true 2.39 strip would be tiny on a phone).
  const bandH = land ? W / 2.39 : H * 0.5;
  const barH = (H - bandH) / 2;
  const close = interpolate(f, [0, Math.round(1.0 * fps)], [0, 1], { ...clamp, easing: EASE });
  const pan = interpolate(f, [0, T], [-3, 3], { ...clamp, easing: Easing.inOut(Easing.sin) });
  const show = (delay: number): React.CSSProperties => {
    const t = interpolate(f, [Math.round(delay * fps), Math.round((delay + 0.7) * fps)], [0, 1], { ...clamp, easing: EASE });
    return { opacity: t, transform: `translateY(${(1 - t) * 20 * u}px)` };
  };

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", overflow: "hidden", backgroundColor: NAVY }}>
      <AbsoluteFill style={{ transform: `scale(1.14) translateX(${pan}%)` }}>
        {src ? <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.88) contrast(1.06)" }} /> : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: barH * close, background: NAVY }} />
      <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: barH * close, background: NAVY }} />
      {eyebrow && !land ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: barH - 96 * u, display: "flex", justifyContent: "center", ...show(0.7) }}>
          <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 36 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, borderBottom: `${3 * u}px solid ${CYAN}`, paddingBottom: 14 * u }}>{eyebrow}</div>
        </div>
      ) : null}
      {caption ? (
        <div
          style={{
            position: "absolute",
            left: 72 * u,
            right: 72 * u,
            top: land ? undefined : H - barH + 56 * u,
            bottom: land ? 40 * u : undefined,
            display: "flex",
            justifyContent: "center",
            textAlign: "center",
            fontFamily: FONTS.display,
            fontVariantNumeric: "lining-nums",
            fontWeight: 300,
            fontSize: (land ? 64 : 96) * u,
            lineHeight: 1.05,
            color: WHITE,
            ...show(0.85),
          }}
        >
          {caption}
        </div>
      ) : null}
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default LetterboxCinema;
